import{_ as t,c as n,j as e,a as l,o as r}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百四十二章 痛苦的根源","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/242第二百四十二章 痛苦的根源.md","filePath":"meditation/巴利文大藏经/242第二百四十二章 痛苦的根源.md"}'),o={name:"meditation/巴利文大藏经/242第二百四十二章 痛苦的根源.md"};function _(s,a,i,d,p,c){return r(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百四十二章-痛苦的根源",tabindex:"-1"},[l("第二百四十二章 痛苦的根源 "),e("a",{class:"header-anchor",href:"#第二百四十二章-痛苦的根源","aria-label":'Permalink to "第二百四十二章 痛苦的根源"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应31经/痛苦之根经(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！如来现在要教导你们：什么是痛苦？什么是痛苦产生的根源？你们要认真的听，你们要仔细的思考，如来要开始说法了。”",-1),e("p",null,"出家弟子们回答：“世尊，我们会认真听您说法的，我们会仔细的思考的，恭请世尊您为他们说法。”",-1),e("p",null,"佛陀说：“比丘们！什么是痛苦呢？物质事物、物质身体就是痛苦，感受、念想、行为、认识、分别、判断就是痛苦。什么是痛苦产生的根源呢？就是对物质事物、物质身体、感受、念想、行为、认识、分别、判断生起快乐、喜悦。对物质事物、物质身体、感受、念想、行为、认识、分别、判断生起贪欲、渴爱，也就是：生起对欲望的渴爱，生起对存在、生存、获得的渴爱，生起对永远解脱生死的渴爱，生起对不生不灭涅槃境界的渴爱，比丘们！这就是痛苦产生的根源。”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(o,[["render",_]]);export{u as __pageData,f as default};
